fn to_lowercase(str1: &Vec<char>) -> Vec<char> {
    let mut result = Vec::with_capacity(str1.len());
    for &ch in str1.iter() {
        // Check if ch is uppercase ASCII 'A'..='Z'
        if ('A'..='Z').contains(&ch) {
            // Convert uppercase to lowercase by adding offset
            // 'A' as u8 = 65, 'a' as u8 = 97, difference = 32
            let lower = ((ch as u8) + 32) as char;
            result.push(lower);
        } else {
            // Otherwise keep the same character
            result.push(ch);
        }
    }
    result
}